import math
import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry convtrans2d_fwd(
    .param .u64 p_x,
    .param .u64 p_w,
    .param .u64 p_b,
    .param .u64 p_y,
    .param .u32 p_N,
    .param .u32 p_Cin,
    .param .u32 p_Cout,
    .param .u32 p_Hin,
    .param .u32 p_Win,
    .param .u32 p_Hout,
    .param .u32 p_Wout,
    .param .u32 p_kH,
    .param .u32 p_kW,
    .param .u32 p_stride_h,
    .param .u32 p_stride_w,
    .param .u32 p_pad_h,
    .param .u32 p_pad_w,
    .param .u32 p_dil_h,
    .param .u32 p_dil_w,
    .param .u32 p_groups,
    .param .u32 p_has_bias
)
{
    .reg .pred  %p<20>;
    // Explicit register declarations to match named registers used below
    .reg .b64 %rdX, %rdW, %rdB, %rdY;
    .reg .b64 %rdTid, %rdT0, %rdT1, %rdTot, %rdT2, %rdT3;
    .reg .b64 %rdXidx, %rdXofs, %rdXaddr;
    .reg .b64 %rdWidx, %rdWofs, %rdWaddr;
    .reg .b64 %rdBidx, %rdBofs, %rdBaddr;
    .reg .b64 %rdYidx, %rdYofs, %rdYaddr;
    .reg .b32 %rN, %rCin, %rCout, %rHin, %rWin, %rHout, %rWout;
    .reg .b32 %rkH, %rkW, %rSh, %rSw, %rPh, %rPw, %rDh, %rDw, %rGroups, %rHasBias;
    .reg .b32 %rTid, %rBlk, %rBDim, %rTmpIdx, %rOw, %rOh, %rOc, %rNidx;
    .reg .b32 %rCoutPer, %rCinPer, %rG, %rOcg, %rCinStart;
    .reg .b32 %rOh_s, %rOw_s, %rPh_s, %rPw_s, %rSh_s, %rSw_s, %rDh_s, %rDw_s;
    .reg .b32 %rKh, %rKw, %rTmpU, %rTmpU2, %rTmpS, %rTmpS2, %rRemH, %rRemW;
    .reg .b32 %rIh_s, %rIw_s, %rIh, %rIw, %rIcg, %rIc, %rTh, %rTw;
    .reg .f32 %fAcc, %fX, %fW, %fB;

    // Load params
    ld.param.u64 %rdX, [p_x];
    ld.param.u64 %rdW, [p_w];
    ld.param.u64 %rdB, [p_b];
    ld.param.u64 %rdY, [p_y];

    ld.param.u32 %rN,       [p_N];
    ld.param.u32 %rCin,     [p_Cin];
    ld.param.u32 %rCout,    [p_Cout];
    ld.param.u32 %rHin,     [p_Hin];
    ld.param.u32 %rWin,     [p_Win];
    ld.param.u32 %rHout,    [p_Hout];
    ld.param.u32 %rWout,    [p_Wout];
    ld.param.u32 %rkH,      [p_kH];
    ld.param.u32 %rkW,      [p_kW];
    ld.param.u32 %rSh,      [p_stride_h];
    ld.param.u32 %rSw,      [p_stride_w];
    ld.param.u32 %rPh,      [p_pad_h];
    ld.param.u32 %rPw,      [p_pad_w];
    ld.param.u32 %rDh,      [p_dil_h];
    ld.param.u32 %rDw,      [p_dil_w];
    ld.param.u32 %rGroups,  [p_groups];
    ld.param.u32 %rHasBias, [p_has_bias];

    // Compute linear thread id
    mov.u32  %rTid, %tid.x;
    mov.u32  %rBlk, %ctaid.x;
    mov.u32  %rBDim, %ntid.x;
    mad.lo.s32 %rTid, %rBlk, %rBDim, %rTid; // rTid = blockIdx.x*blockDim.x + threadIdx.x
    cvt.u64.u32 %rdTid, %rTid;

    // total = N * Cout * Hout * Wout (u64)
    cvt.u64.u32 %rdT0, %rN;
    cvt.u64.u32 %rdT1, %rCout;
    mul.lo.u64  %rdTot, %rdT0, %rdT1;
    cvt.u64.u32 %rdT1, %rHout;
    mul.lo.u64  %rdTot, %rdTot, %rdT1;
    cvt.u64.u32 %rdT1, %rWout;
    mul.lo.u64  %rdTot, %rdTot, %rdT1;

    // Bounds check on global thread id
    setp.ge.u64 %p0, %rdTid, %rdTot;
    @%p0 bra RET;

    // Decode n, oc, oh, ow from rTid (u32)
    mov.u32 %rTmpIdx, %rTid;

    // ow = rTmpIdx % Wout; rTmpIdx = rTmpIdx / Wout
    rem.u32 %rOw, %rTmpIdx, %rWout;
    div.u32 %rTmpIdx, %rTmpIdx, %rWout;

    // oh = rTmpIdx % Hout; rTmpIdx = rTmpIdx / Hout
    rem.u32 %rOh, %rTmpIdx, %rHout;
    div.u32 %rTmpIdx, %rTmpIdx, %rHout;

    // oc = rTmpIdx % Cout; n = rTmpIdx / Cout
    rem.u32 %rOc, %rTmpIdx, %rCout;
    div.u32 %rNidx, %rTmpIdx, %rCout;

    // Compute per-group sizes
    div.u32 %rCoutPer, %rCout, %rGroups;
    div.u32 %rCinPer,  %rCin,  %rGroups;

    // g = oc / CoutPer; ocg = oc % CoutPer
    div.u32 %rG,   %rOc, %rCoutPer;
    rem.u32 %rOcg, %rOc, %rCoutPer;

    // group input channel start = g * CinPer
    mul.lo.u32 %rCinStart, %rG, %rCinPer;

    // Prepare constants in s32 for signed ops
    cvt.s32.u32 %rOh_s, %rOh;
    cvt.s32.u32 %rOw_s, %rOw;
    cvt.s32.u32 %rPh_s, %rPh;
    cvt.s32.u32 %rPw_s, %rPw;
    cvt.s32.u32 %rSh_s, %rSh;
    cvt.s32.u32 %rSw_s, %rSw;
    cvt.s32.u32 %rDh_s, %rDh;
    cvt.s32.u32 %rDw_s, %rDw;

    // Accumulator
    mov.f32 %fAcc, 0f00000000;

    // kh loop
    mov.u32 %rKh, 0;
K_H_LOOP:
    setp.ge.u32 %p1, %rKh, %rkH;
    @%p1 bra K_H_DONE;

    // t_h = oh + pad_h - kh*dil_h
    mul.lo.u32  %rTmpU, %rKh, %rDh;     // kh * dil_h (u32)
    cvt.s32.u32 %rTmpS, %rTmpU;         // to s32
    add.s32     %rTh, %rOh_s, %rPh_s;
    sub.s32     %rTh, %rTh, %rTmpS;

    // if (t_h % stride_h != 0) continue
    rem.s32 %rRemH, %rTh, %rSh_s;
    setp.ne.s32 %p2, %rRemH, 0;
    @%p2 bra K_H_CONT;

    // ih = t_h / stride_h
    div.s32 %rIh_s, %rTh, %rSh_s;
    // if ih < 0 or ih >= Hin -> continue
    setp.lt.s32 %p3, %rIh_s, 0;
    @%p3 bra K_H_CONT;
    cvt.u32.s32 %rIh, %rIh_s;
    setp.ge.u32 %p4, %rIh, %rHin;
    @%p4 bra K_H_CONT;

    // kw loop
    mov.u32 %rKw, 0;
K_W_LOOP:
    setp.ge.u32 %p5, %rKw, %rkW;
    @%p5 bra K_H_CONT;

    // t_w = ow + pad_w - kw*dil_w
    mul.lo.u32  %rTmpU2, %rKw, %rDw;
    cvt.s32.u32 %rTmpS2, %rTmpU2;
    add.s32     %rTw, %rOw_s, %rPw_s;
    sub.s32     %rTw, %rTw, %rTmpS2;

    // if (t_w % stride_w != 0) continue kw++
    rem.s32 %rRemW, %rTw, %rSw_s;
    setp.ne.s32 %p6, %rRemW, 0;
    @%p6 bra K_W_CONT;

    // iw = t_w / stride_w
    div.s32 %rIw_s, %rTw, %rSw_s;
    setp.lt.s32 %p7, %rIw_s, 0;
    @%p7 bra K_W_CONT;
    cvt.u32.s32 %rIw, %rIw_s;
    setp.ge.u32 %p8, %rIw, %rWin;
    @%p8 bra K_W_CONT;

    // ic loop over group input channels
    mov.u32 %rIcg, 0;
IC_LOOP:
    setp.ge.u32 %p9, %rIcg, %rCinPer;
    @%p9 bra IC_DONE;

    add.u32 %rIc, %rCinStart, %rIcg;

    // x index: (((n*Cin + ic)*Hin + ih)*Win + iw)
    cvt.u64.u32 %rdT2, %rNidx;
    cvt.u64.u32 %rdT3, %rCin;
    mul.lo.u64  %rdXidx, %rdT2, %rdT3;               // n*Cin
    cvt.u64.u32 %rdT2, %rIc;
    add.u64     %rdXidx, %rdXidx, %rdT2;             // + ic
    cvt.u64.u32 %rdT3, %rHin;
    mul.lo.u64  %rdXidx, %rdXidx, %rdT3;             // * Hin
    cvt.u64.u32 %rdT2, %rIh;
    add.u64     %rdXidx, %rdXidx, %rdT2;             // + ih
    cvt.u64.u32 %rdT3, %rWin;
    mul.lo.u64  %rdXidx, %rdXidx, %rdT3;             // * Win
    cvt.u64.u32 %rdT2, %rIw;
    add.u64     %rdXidx, %rdXidx, %rdT2;             // + iw
    shl.b64     %rdXofs, %rdXidx, 2;                 // * sizeof(float)
    add.u64     %rdXaddr, %rdX, %rdXofs;
    ld.global.f32 %fX, [%rdXaddr];

    // w index: (((ic*CoutPer + ocg)*kH + kh)*kW + kw)
    cvt.u64.u32 %rdWidx, %rIc;
    cvt.u64.u32 %rdT2, %rCoutPer;
    mul.lo.u64  %rdWidx, %rdWidx, %rdT2;             // ic*CoutPer
    cvt.u64.u32 %rdT2, %rOcg;
    add.u64     %rdWidx, %rdWidx, %rdT2;             // + ocg
    cvt.u64.u32 %rdT2, %rkH;
    mul.lo.u64  %rdWidx, %rdWidx, %rdT2;             // * kH
    cvt.u64.u32 %rdT2, %rKh;
    add.u64     %rdWidx, %rdWidx, %rdT2;             // + kh
    cvt.u64.u32 %rdT2, %rkW;
    mul.lo.u64  %rdWidx, %rdWidx, %rdT2;             // * kW
    cvt.u64.u32 %rdT2, %rKw;
    add.u64     %rdWidx, %rdWidx, %rdT2;             // + kw
    shl.b64     %rdWofs, %rdWidx, 2;
    add.u64     %rdWaddr, %rdW, %rdWofs;
    ld.global.f32 %fW, [%rdWaddr];

    // acc += x * w
    fma.rn.f32 %fAcc, %fX, %fW, %fAcc;

    add.u32 %rIcg, %rIcg, 1;
    bra IC_LOOP;
IC_DONE:

K_W_CONT:
    add.u32 %rKw, %rKw, 1;
    bra K_W_LOOP;

K_H_CONT:
    add.u32 %rKh, %rKh, 1;
    bra K_H_LOOP;

K_H_DONE:

    // Add bias if present
    setp.ne.u32 %p10, %rHasBias, 0;
    @!%p10 bra NO_BIAS;
    cvt.u64.u32 %rdBidx, %rOc;
    shl.b64     %rdBofs, %rdBidx, 2;
    add.u64     %rdBaddr, %rdB, %rdBofs;
    ld.global.f32 %fB, [%rdBaddr];
    add.f32 %fAcc, %fAcc, %fB;
NO_BIAS:

    // Store y at (((n*Cout + oc)*Hout + oh)*Wout + ow)
    cvt.u64.u32 %rdYidx, %rNidx;
    cvt.u64.u32 %rdT2, %rCout;
    mul.lo.u64  %rdYidx, %rdYidx, %rdT2;         // n*Cout
    cvt.u64.u32 %rdT2, %rOc;
    add.u64     %rdYidx, %rdYidx, %rdT2;         // + oc
    cvt.u64.u32 %rdT2, %rHout;
    mul.lo.u64  %rdYidx, %rdYidx, %rdT2;         // * Hout
    cvt.u64.u32 %rdT2, %rOh;
    add.u64     %rdYidx, %rdYidx, %rdT2;         // + oh
    cvt.u64.u32 %rdT2, %rWout;
    mul.lo.u64  %rdYidx, %rdYidx, %rdT2;         // * Wout
    cvt.u64.u32 %rdT2, %rOw;
    add.u64     %rdYidx, %rdYidx, %rdT2;         // + ow
    shl.b64     %rdYofs, %rdYidx, 2;
    add.u64     %rdYaddr, %rdY, %rdYofs;
    st.global.f32 [%rdYaddr], %fAcc;

RET:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("convtrans2d_fwd")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1), padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        if isinstance(kernel_size, int):
            kernel_size = (kernel_size, kernel_size)
        if isinstance(stride, int):
            stride = (stride, stride)
        if isinstance(padding, int):
            padding = (padding, padding)
        if isinstance(dilation, int):
            dilation = (dilation, dilation)
        assert in_channels % groups == 0 and out_channels % groups == 0, "in/out channels must be divisible by groups"

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        # Create a submodule to match state_dict keys: conv_transpose2d.weight / bias
        self.conv_transpose2d = nn.Module()
        kH, kW = kernel_size
        out_per_group = out_channels // groups
        w = torch.empty(in_channels, out_per_group, kH, kW, dtype=torch.float32)
        # Initialize weights similar to PyTorch's default (kaiming_uniform)
        nn.init.kaiming_uniform_(w, a=math.sqrt(5))
        self.conv_transpose2d.weight = nn.Parameter(w)
        if bias:
            # Bias size is [out_channels]
            fan_in = in_channels * kH * kW // groups
            bound = 1 / math.sqrt(fan_in) if fan_in > 0 else 0
            b = torch.empty(out_channels, dtype=torch.float32).uniform_(-bound, bound)
            self.conv_transpose2d.bias = nn.Parameter(b)
        else:
            self.conv_transpose2d.register_parameter("bias", None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be a CUDA tensor"
        assert x.dtype == torch.float32, "Only float32 is supported"
        N, Cin, Hin, Win = x.shape
        Cin_m = self.in_channels
        Cout = self.out_channels
        kH, kW = self.kernel_size
        sh, sw = self.stride
        ph, pw = self.padding
        dh, dw = self.dilation
        G = self.groups
        assert Cin == Cin_m, "Mismatched in_channels"
        assert Cin % G == 0 and Cout % G == 0

        Hout = (Hin - 1) * sh - 2 * ph + dh * (kH - 1) + 1
        Wout = (Win - 1) * sw - 2 * pw + dw * (kW - 1) + 1

        y = torch.empty((N, Cout, Hout, Wout), device=x.device, dtype=x.dtype)

        w = self.conv_transpose2d.weight
        b = self.conv_transpose2d.bias
        has_bias = 1 if b is not None else 0

        module = _get_ptx_module()
        total = N * Cout * Hout * Wout
        block_x = 256
        grid_x = (total + block_x - 1) // block_x
        module.launch(
            "convtrans2d_fwd",
            grid=(int(grid_x), 1, 1),
            block=(block_x, 1, 1),
            arguments=[
                x, w, (b if b is not None else u64(0)), y,
                i32(N), i32(Cin), i32(Cout), i32(Hin), i32(Win),
                i32(Hout), i32(Wout), i32(kH), i32(kW),
                i32(sh), i32(sw), i32(ph), i32(pw), i32(dh), i32(dw),
                i32(G), i32(has_bias),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

