from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry convtrans2d_fwd(
    .param .u64 p_x,
    .param .u64 p_w,
    .param .u64 p_b,
    .param .u64 p_y,
    .param .u32 p_N,
    .param .u32 p_Cin,
    .param .u32 p_Cout,
    .param .u32 p_Hin,
    .param .u32 p_Win,
    .param .u32 p_Hout,
    .param .u32 p_Wout,
    .param .u32 p_kH,
    .param .u32 p_kW,
    .param .u32 p_stride_h,
    .param .u32 p_stride_w,
    .param .u32 p_pad_h,
    .param .u32 p_pad_w,
    .param .u32 p_dil_h,
    .param .u32 p_dil_w,
    .param .u32 p_groups,
    .param .u32 p_has_bias
)
{
    .reg .pred  %p<20>;
    .reg .b32   %r<100>;
    .reg .b64   %rd<60>;
    .reg .f32   %f<10>;

    // Load params
    ld.param.u64 %rdX, [p_x];
    ld.param.u64 %rdW, [p_w];
    ld.param.u64 %rdB, [p_b];
    ld.param.u64 %rdY, [p_y];

    ld.param.u32 %rN,       [p_N];
    ld.param.u32 %rCin,     [p_Cin];
    ld.param.u32 %rCout,    [p_Cout];
    ld.param.u32 %rHin,     [p_Hin];
    ld.param.u32 %rWin,     [p_Win];
    ld.param.u32 %rHout,    [p_Hout];
    ld.param.u32 %rWout,    [p_Wout];
    ld.param.u32 %rkH,      [p_kH];
    ld.param.u32 %rkW,      [p_kW];
    ld.param.u32 %rSh,      [p_stride_h];
    ld.param.u32 %rSw,      [p_stride_w];
    ld.param.u32 %rPh,      [p_pad_h];
    ld.param.u32 %rPw,      [p_pad_w];
    ld.param.u32 %rDh,      [p_dil_h];
    ld.param.u32 %rDw,      [p_dil_w];
    ld.param.u32 %rGroups,  [p_groups];
    ld.param.u32 %rHasBias, [p_has_bias];

    // Compute linear thread id
    mov.u32  %rTid, %tid.x;
    mov.u32  %rBlk, %ctaid.x;
    mov.u32  %rBDim, %ntid.x;
    mad.lo.s32 %rTid, %rBlk, %rBDim, %rTid; // rTid = blockIdx.x*blockDim.x + threadIdx.x
    cvt.u64.u32 %rdTid, %rTid;

    // total = N * Cout * Hout * Wout (u64)
    cvt.u64.u32 %rdT0, %rN;
    cvt.u64.u32 %rdT1, %rCout;
    mul.lo.u64  %rdTot, %rdT0, %rdT1;
    cvt.u64.u32 %rdT1, %rHout;
    mul.lo.u64  %rdTot, %rdTot, %rdT1;
    cvt.u64.u32 %rdT1, %rWout;
    mul.lo.u64  %rdTot, %rdTot, %rdT1;

    // Bounds check on global thread id
    setp.ge.u64 %p0, %rdTid, %rdTot;
    @%p0 bra RET;

    // Decode n, oc, oh, ow from rTid (u32)
    mov.u32 %rTmpIdx, %rTid;

    // ow = rTmpIdx % Wout; rTmpIdx = rTmpIdx / Wout
    rem.u32 %rOw, %rTmpIdx, %rWout;
    div.u32 %rTmpIdx, %rTmpIdx, %rWout;

    // oh = rTmpIdx % Hout; rTmpIdx = rTmpIdx / Hout
    rem.u32 %rOh, %rTmpIdx, %rHout;
    div.u32 %rTmpIdx, %rTmpIdx, %rHout;

    // oc = rTmpIdx % Cout; n = rTmpIdx / Cout
    rem.u32 %rOc, %rTmpIdx, %rCout;
    div.u32 %rNidx, %rTmpIdx, %rCout;

    // Compute per-group sizes
    div.u32 %rCoutPer, %rCout, %rGroups;
    div.u32 %rCinPer,  %rCin,  %rGroups;

    // g = oc / CoutPer; ocg = oc % CoutPer
    div.u32 %rG,   %rOc, %rCoutPer;
    rem.u32 %rOcg, %rOc, %rCoutPer;

    // group input channel start = g * CinPer
    mul.lo.u32 %rCinStart, %rG, %rCinPer;

    // Prepare constants in s32 for signed ops
    cvt.s32.u32 %rOh_s, %rOh;
    cvt.s32.u32 %rOw_s, %rOw;
    cvt.s32.u32 %rPh_s, %rPh;
    cvt.s32.u32 %rPw_s, %rPw;
    cvt.s32.u32 %rSh_s, %rSh;
    cvt.s32.u32 %rSw_s, %rSw;
    cvt.s32.u32 %rDh_s, %rDh;
    cvt.s32.u32 %rDw_s, %rDw;

    // Accumulator
    mov.f32 %fAcc, 0f00000000;

    // kh loop
    mov.u32 %rKh, 0;
K_H_LOOP:
    setp.ge.u32 %p1, %rKh, %rkH;
    @%p1 bra K_H_DONE;

    // t_h = oh + pad_h - kh*dil_h
    mul.lo.u32  %rTmpU, %rKh, %rDh;     // kh * dil_h (u32)
    cvt.s32.u32 %rTmpS, %rTmpU;         // to s32
    add.s32     %rTh, %rOh_s, %rPh_s;
    sub.s32     %rTh, %rTh, %rTmpS;

    // if (t_h % stride_h != 0) continue
    rem.s32 %rRemH, %rTh, %rSh_s;
    setp.ne.s32 %p2, %rRemH, 0;
